const i=10;export function captureDrawn(o){const r=[];for(const e of o||[])e&&typeof e.traverse=="function"&&e.traverse(s=>r.push(s));const t=new Float64Array(r.length*10);return r.forEach((e,s)=>{const n=s*10;t[n]=e.position.x,t[n+1]=e.position.y,t[n+2]=e.position.z,t[n+3]=e.rotation.x,t[n+4]=e.rotation.y,t[n+5]=e.rotation.z,t[n+6]=e.scale.x,t[n+7]=e.scale.y,t[n+8]=e.scale.z,t[n+9]=e.visible?1:0}),{nodes:r,data:t}}export function applyDrawn(o){if(!o||!o.nodes)return!1;const{nodes:r,data:t}=o;return r.forEach((e,s)=>{const n=s*10;e.position.set(t[n],t[n+1],t[n+2]),e.rotation.set(t[n+3],t[n+4],t[n+5]),e.scale.set(t[n+6],t[n+7],t[n+8]),e.visible=t[n+9]===1}),!0}export function snapshotSize(o){return o&&o.nodes?o.nodes.length:0}
